class TransientError(Exception):
    """A retryable transport failure."""


class PermanentError(Exception):
    """A non-retryable transport failure."""


def call_with_retry(endpoint_cfg: dict, transport) -> dict:
    """Invoke a transport according to the endpoint's retry-count convention."""
    max_attempts = max(1, endpoint_cfg["retry"] + 1)
    attempts = 0

    while attempts < max_attempts:
        attempts += 1
        try:
            value = transport(endpoint_cfg["url"], endpoint_cfg["timeout_ms"])
        except PermanentError as exc:
            return {
                "ok": False,
                "attempts": attempts,
                "result": None,
                "error": {
                    "type": "permanent",
                    "message": str(exc),
                },
            }
        except TransientError as exc:
            if attempts < max_attempts:
                continue
            return {
                "ok": False,
                "attempts": attempts,
                "result": None,
                "error": {
                    "type": "transient",
                    "message": str(exc),
                },
            }
        else:
            return {
                "ok": True,
                "attempts": attempts,
                "result": value,
                "error": None,
            }

    raise RuntimeError("retry configuration produced no attempt")
